"""Scrapy middleware definitions for the arXiv scraper.

The project currently relies on scrapy-splash middleware configured in
``settings.py``. These boilerplate classes keep Scrapy imports working if the
project later enables its local middleware hooks.
"""

from __future__ import annotations

from scrapy import signals


class ArxivScraperSpiderMiddleware:
    """Default spider middleware scaffold generated by Scrapy."""

    @classmethod
    def from_crawler(cls, crawler):
        middleware = cls()
        crawler.signals.connect(middleware.spider_opened, signal=signals.spider_opened)
        return middleware

    def process_spider_input(self, response, spider):
        return None

    def process_spider_output(self, response, result, spider):
        yield from result

    def process_spider_exception(self, response, exception, spider):
        return None

    def process_start_requests(self, start_requests, spider):
        yield from start_requests

    def spider_opened(self, spider):
        spider.logger.info("Spider opened: %s", spider.name)


class ArxivScraperDownloaderMiddleware:
    """Default downloader middleware scaffold generated by Scrapy."""

    @classmethod
    def from_crawler(cls, crawler):
        middleware = cls()
        crawler.signals.connect(middleware.spider_opened, signal=signals.spider_opened)
        return middleware

    def process_request(self, request, spider):
        return None

    def process_response(self, request, response, spider):
        return response

    def process_exception(self, request, exception, spider):
        return None

    def spider_opened(self, spider):
        spider.logger.info("Spider opened: %s", spider.name)
